import Ajv, {type Options, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

function formatValidationError(validator: ValidateFunction): {path: string; result: string} {
  const error = validator.errors?.[0];
  const path = getValidationPath(error);
  const missingProperty = hasMissingProperty(error?.params) ? error.params.missingProperty : undefined;
  const parentPath = path.replace(/^\//, '').replaceAll('/', '.');
  const property = error?.keyword === 'required' ? [parentPath, missingProperty].filter(Boolean).join('.') : parentPath;
  const detail =
    error?.keyword === 'required'
      ? `${property} is required`
      : `${property || 'input'} ${error?.keyword ?? 'validation'}: ${error?.message ?? 'is invalid'}`;
  return {path: property || 'input', result: `Invalid input: ${detail}`};
}

function hasMissingProperty(params: unknown): params is {missingProperty: string} {
  if (typeof params !== 'object' || params === null) return false;
  return 'missingProperty' in params && typeof params.missingProperty === 'string';
}

function getValidationPath(error: unknown): string {
  if (typeof error !== 'object' || error === null) return '';
  if ('instancePath' in error && typeof error.instancePath === 'string') return error.instancePath;
  if ('dataPath' in error && typeof error.dataPath === 'string') return error.dataPath;
  return '';
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({
    strict: false,
    validateFormats: false,
    coerceTypes: false,
    useDefaults: false,
  } as Options);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compile(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  private compile(name: string, schema: Record<string, unknown>): ValidateFunction {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    try {
      const validator = this.ajv.compile(schema);
      this.validators.set(schema, validator);
      return validator;
    } catch (error) {
      const message = `Invalid inputSchema for tool ${name}: ${error instanceof Error ? error.message : String(error)}`;
      throw new Error(message, {cause: error});
    }
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a registered tool after schema validation; rejected input returns a ToolResponse and unknown tools throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.compile(definition.name, definition.inputSchema);
    if (!validator(input)) {
      const rejection = formatValidationError(validator);
      const validationError = validator.errors?.[0];
      log.warn('tool', 'input rejected', {name, path: rejection.path, keyword: validationError?.keyword});
      return {result: rejection.result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema compilation', () => {
  it('reuses a static schema validator across executions', async () => {
    const registry = new ToolRegistry();
    const inputSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema,
      },
      async () => 'sunny'
    );

    inputSchema.type = 'not-a-schema-type';
    const responses = await Promise.all(
      Array.from({length: 10}, () => registry.execute('get_weather', {location: 'Paris'}))
    );

    expect(responses).toEqual(Array.from({length: 10}, () => ({result: 'sunny'})));
  });

  it('passes valid input with undeclared properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', requestId: 'opaque-id'};
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather_with_metadata',
        description: 'Get weather with request metadata',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async receivedInput => {
        executorInputs.push(receivedInput);
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather_with_metadata', input);

    expect({response, executorInputs}).toEqual({
      response: {result: 'sunny'},
      executorInputs: [input],
    });
  });

  it('validates a function-valued definition against the schema returned for each call', async () => {
    const registry = new ToolRegistry();
    let requiredField = 'location';
    const executorInputs: Array<Record<string, unknown>> = [];

    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Get weather with a dynamic schema',
        inputSchema: {
          type: 'object',
          properties: {[requiredField]: {type: 'string'}},
          required: [requiredField],
        },
      }),
      async input => {
        executorInputs.push(input);
        return 'sunny';
      }
    );

    const firstResponse = await registry.execute('dynamic_weather', {location: 'Paris'});
    requiredField = 'city';
    const secondResponse = await registry.execute('dynamic_weather', {city: 'Berlin'});

    expect({firstResponse, secondResponse, executorInputs}).toEqual({
      firstResponse: {result: 'sunny'},
      secondResponse: {result: 'sunny'},
      executorInputs: [{location: 'Paris'}, {city: 'Berlin'}],
    });
  });

  it('names the complete path for a nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_weather',
        description: 'Get weather with nested location data',
        inputSchema: {
          type: 'object',
          properties: {
            location: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('nested_weather', {location: {}});

    expect(response.result).toMatch(/location\.city is required/);
  });

  it('names the field path for a wrong-typed property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'typed_weather',
        description: 'Get typed weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('typed_weather', {location: 42});

    expect({
      namesField: response.result.includes('location'),
      namesExpectedType: response.result.includes('string'),
      omitsOffendingValue: !response.result.includes('42'),
    }).toEqual({
      namesField: true,
      namesExpectedType: true,
      omitsOffendingValue: true,
    });
  });

  it('names enum as the failed constraint without echoing the rejected value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'enum_weather',
        description: 'Get weather with a supported unit',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('enum_weather', {unit: 'kelvin'});

    expect({
      namesField: response.result.includes('unit'),
      namesConstraint: response.result.includes('enum'),
      omitsOffendingValue: !response.result.includes('kelvin'),
    }).toEqual({
      namesField: true,
      namesConstraint: true,
      omitsOffendingValue: true,
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

The release carrying this validation change increments the package MINOR version because the executor input contract changes: malformed calls no longer reach executors ([validated by: publishes the input validation change under the next MINOR version](../../scripts/tool-input-validation-release.test.ts#L11)).

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [missing required location is rejected before the executor runs](../../src/orchestration/tools/registry.test.ts#L3)).
- For a nested missing property, the rejection names the complete dotted property path ([validated by: names the complete path for a nested required property](../../src/orchestration/tools/registry.test.ts#L89)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [names the field path for a wrong-typed property](../../src/orchestration/tools/registry.test.ts#L115)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
  ([validated by: passes valid input with undeclared properties through unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L29), [enum rejection names the failed constraint without echoing the rejected value](../../src/orchestration/tools/registry.test.ts#L143))
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: reuses a static schema validator across executions](../../src/orchestration/tools/registry.test.ts#L4)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.
  ([validated by: validates a function-valued definition against the schema returned for each call](../../src/orchestration/tools/registry.test.ts#L57))

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
